#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m05-component-hunt pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m05-component-hunt
CHECKS="node-kube-apiserver runs-as-kube-apiserver node-etcd runs-as-etcd node-kube-scheduler runs-as-kube-scheduler node-kube-controller-manager runs-as-kube-controller-manager"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m05-component-hunt
checks:
  - id: node-kube-apiserver
    describe: kube-apiserver runs on the node that answers.yaml names
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-apiserver
        - -o
        - json
      jsonpath: "{.items[0].spec.nodeName}"
    expect:
      jsonpath: "{.kube-apiserver.node}"
      matches: (?i)^\s*${derived}\s*$
    hint: List the Pods in kube-system with `kubectl get pods --namespace kube-system --output wide` and read the NODE column of the kube-apiserver Pod.
  - id: runs-as-kube-apiserver
    describe: kube-apiserver is a static Pod, as answers.yaml says
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-apiserver
        - -o
        - json
      jsonpath: "{.items[0].metadata.ownerReferences[0].kind}"
    expect:
      jsonpath: "{.kube-apiserver.runs-as}"
      matches: (?i)^\s*(static[ -]?pod|${derived})\s*$
    hint: A static Pod is owned by the Node it runs on, and its name ends with the node name. Check `kubectl get pod <name> --namespace kube-system --output jsonpath='{.metadata.ownerReferences[0].kind}'`.
  - id: node-etcd
    describe: etcd runs on the node that answers.yaml names
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=etcd
        - -o
        - json
      jsonpath: "{.items[0].spec.nodeName}"
    expect:
      jsonpath: "{.etcd.node}"
      matches: (?i)^\s*${derived}\s*$
    hint: List the Pods in kube-system with `kubectl get pods --namespace kube-system --output wide` and read the NODE column of the etcd Pod.
  - id: runs-as-etcd
    describe: etcd is a static Pod, as answers.yaml says
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=etcd
        - -o
        - json
      jsonpath: "{.items[0].metadata.ownerReferences[0].kind}"
    expect:
      jsonpath: "{.etcd.runs-as}"
      matches: (?i)^\s*(static[ -]?pod|${derived})\s*$
    hint: A static Pod is owned by the Node it runs on, and its name ends with the node name. Check `kubectl get pod <name> --namespace kube-system --output jsonpath='{.metadata.ownerReferences[0].kind}'`.
  - id: node-kube-scheduler
    describe: kube-scheduler runs on the node that answers.yaml names
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-scheduler
        - -o
        - json
      jsonpath: "{.items[0].spec.nodeName}"
    expect:
      jsonpath: "{.kube-scheduler.node}"
      matches: (?i)^\s*${derived}\s*$
    hint: List the Pods in kube-system with `kubectl get pods --namespace kube-system --output wide` and read the NODE column of the kube-scheduler Pod.
  - id: runs-as-kube-scheduler
    describe: kube-scheduler is a static Pod, as answers.yaml says
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-scheduler
        - -o
        - json
      jsonpath: "{.items[0].metadata.ownerReferences[0].kind}"
    expect:
      jsonpath: "{.kube-scheduler.runs-as}"
      matches: (?i)^\s*(static[ -]?pod|${derived})\s*$
    hint: A static Pod is owned by the Node it runs on, and its name ends with the node name. Check `kubectl get pod <name> --namespace kube-system --output jsonpath='{.metadata.ownerReferences[0].kind}'`.
  - id: node-kube-controller-manager
    describe: kube-controller-manager runs on the node that answers.yaml names
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-controller-manager
        - -o
        - json
      jsonpath: "{.items[0].spec.nodeName}"
    expect:
      jsonpath: "{.kube-controller-manager.node}"
      matches: (?i)^\s*${derived}\s*$
    hint: List the Pods in kube-system with `kubectl get pods --namespace kube-system --output wide` and read the NODE column of the kube-controller-manager Pod.
  - id: runs-as-kube-controller-manager
    describe: kube-controller-manager is a static Pod, as answers.yaml says
    file: component-hunt/answers.yaml
    derive:
      kubectl:
        - get
        - pods
        - -n
        - kube-system
        - -l
        - component=kube-controller-manager
        - -o
        - json
      jsonpath: "{.items[0].metadata.ownerReferences[0].kind}"
    expect:
      jsonpath: "{.kube-controller-manager.runs-as}"
      matches: (?i)^\s*(static[ -]?pod|${derived})\s*$
    hint: A static Pod is owned by the Node it runs on, and its name ends with the node name. Check `kubectl get pod <name> --namespace kube-system --output jsonpath='{.metadata.ownerReferences[0].kind}'`.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
